# WRF Extreme Rainfall Classification (mm)
# Simplified legend for Extreme Rainfall layer.

CLASS
    NAME "Heavy Rainfall (20-50 mm)"
    EXPRESSION ([rainfall_mm] > 20 AND [rainfall_mm] <= 50)
    STYLE
        COLOR 152 223 238
        OUTLINECOLOR 152 223 238
    END
END

CLASS
    NAME "Very Heavy Rainfall (50-100 mm)"
    EXPRESSION ([rainfall_mm] > 50 AND [rainfall_mm] <= 100)
    STYLE
        COLOR 43 123 216
        OUTLINECOLOR 43 123 216
    END
END

CLASS
    NAME "Extremely Heavy Rainfall (>100 mm)"
    EXPRESSION ([rainfall_mm] > 100)
    STYLE
        COLOR 9 26 136
        OUTLINECOLOR 9 26 136
    END
END
